window.kbPageData["views/entry/k-088422e0d4693192"] = {"key":"entry/k-088422e0d4693192","state":{"route":"entry/k-088422e0d4693192"},"node":{"id":"k-088422e0d4693192","mode":"k","title":"新兴职业领域增设职称系列","type":"制度与规则","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":["探索在新兴职业领域增设职称系列"],"qs":["江苏 2022 A类 申论#2"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"中共中央办公厅、国务院办公厅印发的《关于深化职称制度改革的意见》（中办发〔2016〕77号）提出，探索在新兴职业领域增设职称系列。新设系列由中央和国家机关有关部门提出，经人力资源社会保障部审核后报国务院批准，各地区各部门未经批准不得自行设置。","review":{"definition":"中共中央办公厅、国务院办公厅印发的《关于深化职称制度改革的意见》（中办发〔2016〕77号）提出，探索在新兴职业领域增设职称系列。新设系列由中央和国家机关有关部门提出，经人力资源社会保障部审核后报国务院批准，各地区各部门未经批准不得自行设置。","explanation":"材料5将《意见》归于人社部，正式印发主体为两办，人社部承担审核职责。材料中的B市科学传播专业职称让科普从业者的业绩有了相应的评价渠道，体现了题干所说的政府适当引导。文件同时允许在职称系列内按专业领域设置专业类别，材料中的专业职称是说明评价渠道如何拓宽的例子。","references":[{"source":"web-045835301a955279","location":"二、健全职称制度体系，（四）完善职称系列","quote":"探索在新兴职业领域增设职称系列。"}],"evidence":"探索在新兴职业领域增设职称系列","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2022 A类 申论#2":{"paper":"江苏 2022 A类 申论","n":2,"mod":"申论","src":["a758d1c52c0259ca1b92.pdf",6],"asrc":["a758d1c52c0259ca1b92.pdf",7],"card":"168b6656be890b2ff0224467","links":[{"id":"k-088422e0d4693192","role":"解题依据","why":"这项改革为原先缺少申报渠道的新兴职业从业者提供职称评价途径。"}]}},"terms":{},"references":{"web-045835301a955279":{"name":"《关于深化职称制度改革的意见》（中办发〔2016〕77号，青岛市人力资源和社会保障局转载）","url":"https://hrss.qingdao.gov.cn/ztzl_47/zcpd_47/zczc_47/qtzc_47/202207/t20220718_6272319.shtml"}},"topics":[],"units":{"k-088422e0d4693192":[["江苏 2022 A类 申论#2"]]}};
